#!/usr/bin/env bash
set -Eeuo pipefail
validate_deployment_id() { case "$1" in ????[0-1][0-9][0-3][0-9]-[0-2][0-9][0-5][0-9][0-5][0-9]-[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]) return 0;; *) return 1;; esac; }
require_clean_tree() { [ -z "$(git -C "$PROJECT_ROOT" status --porcelain)" ] || die 3 'working tree must be clean'; git -C "$PROJECT_ROOT" symbolic-ref -q HEAD >/dev/null || die 3 'detached HEAD is not permitted'; }
require_cutover_confirmation() { [ "${DEPLOY_TEST_CONFIRM:-0}" = 1 ] && return; printf '\nWARNING: this replaces the verified production database and syncs uploads.\nTarget: %s\nRoot: %s\nDatabase: %s\nCommit: %s\n' "$PRODUCTION_URL" "$PRODUCTION_ROOT" "$PRODUCTION_EXPECTED_DB_NAME" "$GIT_COMMIT" >&2; local a b c; printf 'Type production hostname: '; IFS= read -r a; printf 'Type REPLACE-PRODUCTION: '; IFS= read -r b; printf 'Type expected production database name: '; IFS= read -r c; [ "$a" = rentacarvenezia.it ] && [ "$b" = REPLACE-PRODUCTION ] && [ "$c" = "$PRODUCTION_EXPECTED_DB_NAME" ] || die 4 'cutover confirmation did not match'; }
require_rollback_confirmation() { [ "${DEPLOY_TEST_CONFIRM:-0}" = 1 ] && return; local a b c; printf 'Type production hostname: '; IFS= read -r a; printf 'Type ROLLBACK-PRODUCTION: '; IFS= read -r b; printf 'Type expected production database name: '; IFS= read -r c; [ "$a" = rentacarvenezia.it ] && [ "$b" = ROLLBACK-PRODUCTION ] && [ "$c" = "$PRODUCTION_EXPECTED_DB_NAME" ] || die 4 'rollback confirmation did not match'; }
acquire_locks() { [ "${DRY_RUN:-0}" -eq 1 ] && { dry 'would acquire local and remote locks'; return; }; LOCAL_LOCK="$PROJECT_ROOT/runtime/deployment/production.lock"; mkdir -p "$(dirname "$LOCAL_LOCK")"; mkdir "$LOCAL_LOCK" 2>/dev/null || die 6 "local deployment lock exists: $LOCAL_LOCK"; printf '%s %s %s\n' "$DEPLOYMENT_ID" "$(hostname)" "$COMMAND" > "$LOCAL_LOCK/owner"; remote_exec "mkdir -p $(shell_quote "$REMOTE_BACKUP_ROOT") && mkdir $(shell_quote "$REMOTE_BACKUP_ROOT/.production-deploy-lock")" || die 6 'remote deployment lock exists'; remote_exec "printf '%s\\n' $(shell_quote "$DEPLOYMENT_ID $(hostname) $COMMAND") > $(shell_quote "$REMOTE_BACKUP_ROOT/.production-deploy-lock/owner")"; trap release_locks EXIT; }
release_locks() { [ "${DRY_RUN:-0}" -eq 1 ] && return; [ -n "${LOCAL_LOCK:-}" ] && { rm -f "$LOCAL_LOCK/owner"; rmdir "$LOCAL_LOCK" 2>/dev/null || true; }; [ -n "${REMOTE_BACKUP_ROOT:-}" ] && remote_exec "rm -f $(shell_quote "$REMOTE_BACKUP_ROOT/.production-deploy-lock/owner") && rmdir $(shell_quote "$REMOTE_BACKUP_ROOT/.production-deploy-lock") 2>/dev/null || true" >/dev/null 2>&1 || true; }
